pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor) public {
        // actor can be any address except the owner (owner approval path unchanged);
        // keep the domain wide but avoid zero weirdness.
        vm.assume(actor != address(0));
        vm.assume(actor != address(this)); // test contract is the deployer/owner

        // The deployer (this test contract) is the owner in the reference;
        // call the owner-gated setter explicitly from the owner.
        vm.prank(address(this));
        c.setApprovedLogger(actor, true);

        // General rule: an owner-approved logger is reported as approved.
        assertTrue(c.approvedToLog(actor));
    }
}

