pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address logger, bool status) public {
        vm.assume(logger != address(0));
        // actor is owner-side caller: only owner (this contract, the deployer) may set loggers.
        vm.prank(actor);
        bool ok;
        try c.setApprovedLogger(logger, status) { ok = true; } catch { ok = false; }
        if (actor != address(this)) {
            assertTrue(!ok || c.approvedLoggers(logger) == status);
        } else {
            assertTrue(ok && c.approvedLoggers(logger) == status);
        }
    }
}

