pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address logger, address keep) public {
        vm.assume(logger != address(0));
        address owner = c.approvedToLog(logger) ? address(0) : address(this);
        // approve the fuzzed logger via the owner-gated setter
        vm.prank(address(this));
        c.setApprovedLogger(logger, true);
        vm.prank(logger);
        bool ok = c.logCreated(keep);
        assertTrue(ok, "approved logger must get true from logCreated");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test() public returns (bool) {
        // msg.sender is this test contract, which was never approved as a logger
        bool logResult = c.logFunded();
        bool approved = c.approvedToLog(address(this));
        assert(logResult == approved);
        return logResult;
    }
}

