contract InvMutTest {
    C private c;

    constructor(C _c) {
        c = _c;
    }

    function testOnlyOwnerEnforced() public {
        // The contract owner is unset (address(0)); this test contract's
        // address is therefore never the owner.
        // A non-owner's attempt to set an approved logger must revert.
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.setApprovedLogger.selector,
                address(this),
                true
            )
        );
        assert(!ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address logger, bool status) public {
        bool r1;
        bool ok;
        try c.setApprovedLogger(logger, status) { ok = true; } catch { ok = false; }
        r1 = c.approvedToLog(logger);
        assert(!(ok && status && !r1));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address x) public payable {
        require(x != address(0), "bad input");
        bool before = c.approvedLoggers(x);
        bool reverted;
        try c.setApprovedLogger(x, true) { reverted = false; } catch { reverted = true; }
        bool after = c.approvedLoggers(x);
        assert(reverted && after == before);
    }
    receive() external payable {}
}
